package com.aliothmoon.maafw.once;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.file.*;
import java.util.*;
public class RootSelectedPendingScopeTest {
 @Test public void exactlySixPhaseClaimsAndNoOverrun(){assertTrue(RootSelectedPendingScope.ACTIVE);assertEquals(3,RootSelectedPendingScope.MAX_PER_PHASE);assertEquals(6,RootSelectedPendingScope.MAX_FRAMES);Set<String> slots=new HashSet<>();for(var p:NativeRewardCardSession.Phase.values())for(int i=1;i<=3;i++)assertTrue(slots.add(RootSelectedPendingScope.slot(p,i)));assertEquals(Set.of("BEFORE_1","BEFORE_2","BEFORE_3","AFTER_1","AFTER_2","AFTER_3"),slots);for(int i:new int[]{Integer.MIN_VALUE,-1,0,4,Integer.MAX_VALUE}){assertFalse(RootSelectedPendingScope.validIndex(i));assertThrows(SecurityException.class,()->RootSelectedPendingScope.slot(NativeRewardCardSession.Phase.BEFORE,i));}assertThrows(SecurityException.class,()->RootSelectedPendingScope.slot(null,1));}
 @Test public void halfOpenAdmissionKeepsOriginal180s(){long s=RootSelectedPendingScope.STARTS_UTC,e=RootSelectedPendingScope.EXPIRES_UTC;assertFalse(RootSelectedPendingScope.current(s-1));assertTrue(RootSelectedPendingScope.current(s));assertTrue(RootSelectedPendingScope.current(e-1));assertFalse(RootSelectedPendingScope.current(e));assertTrue(RootSelectedPendingScope.admissionCurrent(e-180001));assertFalse(RootSelectedPendingScope.admissionCurrent(e-180000));assertEquals(181000,RootSelectedPendingScope.sessionDeadline(1000,s));}
 @Test public void phaseDeadlineCannotExceedParentOrUtc(){long u=RootSelectedPendingScope.STARTS_UTC;assertEquals(91000,RootSelectedPendingScope.deadline(1000,u,181000));assertEquals(181000,RootSelectedPendingScope.deadline(101000,u+100000,181000));assertEquals(1500,RootSelectedPendingScope.deadline(1000,u,1500));assertEquals(1001,RootSelectedPendingScope.deadline(1000,RootSelectedPendingScope.EXPIRES_UTC-1,181000));}
 @Test public void invalidClocksFailClosed(){long u=RootSelectedPendingScope.STARTS_UTC;assertThrows(SecurityException.class,()->RootSelectedPendingScope.sessionDeadline(-1,u));assertThrows(SecurityException.class,()->RootSelectedPendingScope.sessionDeadline(Long.MAX_VALUE,u));assertThrows(SecurityException.class,()->RootSelectedPendingScope.sessionDeadline(1,RootSelectedPendingScope.EXPIRES_UTC));assertThrows(SecurityException.class,()->RootSelectedPendingScope.deadline(1,u,1));assertThrows(SecurityException.class,()->RootSelectedPendingScope.deadline(-1,u,100));assertThrows(SecurityException.class,()->RootSelectedPendingScope.deadline(Long.MAX_VALUE,u,Long.MAX_VALUE));}
 @Test public void onlyNewNamespaceAndFixedActionSlots()throws Exception{assertEquals(15,RootSelectedPendingScope.SOURCE_TASK_ID);assertNotEquals(RootSelectedPendingScope.DIRECTORY,RootBoundedBusinessScope.DIRECTORY);assertNotEquals(RootSelectedPendingScope.DIRECTORY,RootCurrentCardScope.DIRECTORY);assertNotEquals(RootSelectedPendingScope.DIRECTORY,RootImageSeriesScope.DIRECTORY);assertNotEquals(RootSelectedPendingScope.DIRECTORY,RootFamilyDiagnosticProfile.DIRECTORY);assertNotEquals(RootSelectedPendingScope.DIRECTORY,AutonomousRewardCardScope.DIRECTORY);assertNotEquals(RootSelectedPendingScope.DIRECTORY,RootCaptureScope.PREFLIGHT_DIRECTORY);assertThrows(SecurityException.class,()->RootSelectedPendingScope.store(null,NativeRewardCardSession.Phase.BEFORE,1));assertThrows(SecurityException.class,()->RootSelectedPendingScope.burnAction(Path.of("unused"),"BEFORE","safe"));assertThrows(SecurityException.class,()->RootSelectedPendingScope.burnAction(Path.of("unused"),"../TAP","safe"));assertThrows(SecurityException.class,()->RootSelectedPendingScope.burnAction(null,"TAP","safe"));}
 @Test public void badClaimsAndOversizedMetadataNeverWrite()throws Exception{var store=RootSelectedPendingScope.store(Path.of("unused"),NativeRewardCardSession.Phase.BEFORE,1);assertThrows(SecurityException.class,()->store.burn("invalid","safe"));assertThrows(SecurityException.class,()->store.burn("11111111-1111-1111-1111-111111111111",null));assertThrows(SecurityException.class,()->store.burn("11111111-1111-1111-1111-111111111111","x".repeat(2049)));assertThrows(SecurityException.class,()->RootSelectedPendingScope.burnAction(Path.of("unused"),"RETURN",null));}
 @Test public void durablePrimitiveHasNoRecoveryOrTruncate()throws Exception{Path p=Path.of("../app/src/main/java/com/aliothmoon/maafw/once/RootSelectedPendingScope.java");if(!Files.exists(p))p=Path.of("app/src/main/java/com/aliothmoon/maafw/once/RootSelectedPendingScope.java");String s=Files.readString(p);assertTrue(s.contains("StandardOpenOption.CREATE_NEW"));assertTrue(s.contains("c.force(true)"));assertFalse(s.contains("delete("));assertFalse(s.contains("TRUNCATE_EXISTING"));assertTrue(s.contains("maxFrames=6 maxPerPhase=3 maxTap=1 maxReturn=1"));}
}
